// Generated ids (transaction ids, ...) come from crypto.randomUUID; a counter keeps the file reproducible.
let uuidCounter = 0;
Object.defineProperty(globalThis.crypto, 'randomUUID', {
  configurable: true,
  value: () => `${(++uuidCounter).toString(16).padStart(8, '0')}-0000-4000-8000-000000000000`,
});

let seed = 20261112;
const rand = (n: number): number => { seed = (Math.imul(seed, 1664525) + 1013904223) >>> 0; return (seed >>> 8) % n; };
const pick = <T,>(items: readonly T[]): T => items[rand(items.length)]!;
const chance = (n: number): boolean => rand(n) === 0;
const clone = <T,>(value: T): T => JSON.parse(JSON.stringify(value)) as T;

type Options = { readOnly?: boolean; actor?: { id: string; kind: string }; basePath?: string; cors?: { origins: '*' | string[]; headers?: string[]; maxAge?: number }; maxBodyBytes?: number };
type Request = { method: string; path: string; headers?: Record<string, string>; body?: string };
type Step = { now: string; request: Request; response: { status: number; headers: Record<string, string>; json?: unknown; text?: string } };
type Scenario = { name: string; document: ResearchDocument; options: Options; steps: Step[] };

const BASE_MS = Date.parse('2026-11-12T10:00:00Z');
const iso = (n: number): string => new Date(BASE_MS + n * 1000).toISOString();

