function build(name: string, operations: Operation[]): ResearchDocument {
  let at = '2026-11-12T09:00:00Z';
  const editor = createEditor(createDocument({ id: `doc-${name}`, title: `Report ${name}` }, { now: () => at }), { now: () => at });
  at = '2026-11-12T09:00:01Z';
  const result = editor.apply({ id: `seed-${name}`, actor: { id: 'seed', kind: 'system' }, baseRevision: 0, operations });
  if (!result.ok) throw new Error(`${name}: ${JSON.stringify(result.issues)}`);
  return clone(editor.getSnapshot());
}
