// ---- the harness -------------------------------------------------------------------------------------------------------

class Harness {
  readonly service; readonly handler; readonly steps: Step[] = []; clockIndex = 0; clock = iso(0);
  constructor(readonly name: string, readonly document: ResearchDocument, readonly options: Options = {}) {
    this.service = createReportService(createEditor(clone(document), { now: () => this.clock }));
    this.handler = createHttpHandler(this.service, { ...options, now: () => this.clock } as never);
  }
  async send(request: Request): Promise<Step['response']> {
    this.clockIndex++; this.clock = iso(this.clockIndex);
    const headers = new Headers(request.headers ?? {});
    if (request.body !== undefined && !headers.has('content-type') && !request.headers?.['x-no-content-type']) headers.set('content-type', 'application/json');
    headers.delete('x-no-content-type');
    const init: RequestInit = { method: request.method, headers, ...(request.body === undefined ? {} : { body: request.body }) };
    const response = await this.handler(new Request(`http://localhost${request.path}`, init));
    const out: Step['response'] = { status: response.status, headers: Object.fromEntries([...response.headers.entries()].sort(([x], [y]) => x < y ? -1 : 1)) };
    const text = await response.text();
    if ((response.headers.get('content-type') ?? '').startsWith('application/json') && text !== '') out.json = JSON.parse(text); else out.text = text;
    this.steps.push({ now: this.clock, request, response: out });
    return out;
  }
  action(name: string, input: unknown, extra: Partial<Request> = {}): Promise<Step['response']> {
    return this.send({ method: 'POST', path: `/actions/${name}`, body: JSON.stringify(input), ...extra });
  }
  scenario(): Scenario { return { name: this.name, document: this.document, options: this.options, steps: this.steps }; }
}
