// ---- mutated inputs -------------------------------------------------------------------------------------------------------

function mutate(value: unknown): unknown {
  const copy = clone(value) as Record<string, unknown>;
  const keys = Object.keys(copy);
  const how = rand(10);
  if (how === 0 && keys.length) delete copy[pick(keys)];
  else if (how === 1) copy.unexpected = 1;
  else if (how === 2 && keys.length) copy[pick(keys)] = pick([null, 7, -1, 1.5, 'str', true, [], {}, [1], { a: 1 }, '', 'x'.repeat(5000), 9007199254740992, Number.MAX_SAFE_INTEGER, 1e21]);
  else if (how === 3 && keys.length) copy[pick(keys)] = pick(['bad id', '', '-lead', 'a'.repeat(129), 'ok-id', 'ünï']);
  else if (how === 4) return pick([null, [], 'string', 5, true]);
  else if (how === 5 && keys.length) { const key = pick(keys); copy[key] = Array.isArray(copy[key]) ? [] : typeof copy[key] === 'string' ? ['x'] : copy[key]; }
  else if (how === 6) copy.dryRun = pick([true, false, 'yes']);
  else if (how === 7) copy.transactionId = pick(['bad id', 7, 't-ok-' + rand(1000)]);
  else if (how === 8) copy.expectedRevision = pick([-1, 1.5, 'x', 999]);
  return copy;
}
